#!/usr/bin/env node
/**
 * Differential harness: run the reference executable and the Node port with the
 * same arguments and compare stdout and exit status byte for byte.
 */
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test20_executable';
const JS = ['/output/test20.mjs'];

export function runCase(argv, timeout = 20000) {
  const ref = spawnSync(REF, argv, { encoding: 'latin1', timeout, maxBuffer: 1 << 28 });
  const js = spawnSync('node', [...JS, ...argv], { encoding: 'latin1', timeout, maxBuffer: 1 << 28 });
  const norm = (r) => ({
    out: r.stdout === null ? '' : r.stdout,
    err: r.stderr === null ? '' : r.stderr,
    code: r.status === null ? `signal:${r.signal}` : r.status,
  });
  const a = norm(ref);
  const b = norm(js);
  return { ok: a.out === b.out && a.code === b.code, ref: a, js: b, argv };
}

export function describe(argv) {
  return argv.map((x) => JSON.stringify(x)).join(' ');
}

export function report(results, { showStderr = false } = {}) {
  let pass = 0;
  const failures = [];
  for (const r of results) {
    if (r.ok) pass += 1;
    else failures.push(r);
  }
  console.log(`${pass}/${results.length} passed`);
  for (const f of failures.slice(0, 12)) {
    console.log('\n--- FAIL: ' + describe(f.argv));
    console.log(`exit: ref=${f.ref.code} js=${f.js.code}`);
    const refLines = f.ref.out.split('\n');
    const jsLines = f.js.out.split('\n');
    for (let i = 0; i < Math.max(refLines.length, jsLines.length); i += 1) {
      if (refLines[i] !== jsLines[i]) {
        console.log(`  line ${i + 1}: ref=${JSON.stringify(refLines[i])} js=${JSON.stringify(jsLines[i])}`);
      }
    }
    if (showStderr) {
      console.log('  ref stderr: ' + JSON.stringify(f.ref.err));
      console.log('  js  stderr: ' + JSON.stringify(f.js.err));
    }
  }
  return failures.length === 0;
}

